<script lang="ts">
 import Modal from './Modal.svelte';import Feedback from './Feedback.svelte';import StatusPill from '../workspace/StatusPill.svelte';import {Button} from '#lib/components/ui/button/index.ts';import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import {APPOINTMENT_STATUS_LABELS} from '#lib/constants/appointment.ts';import type {ApiPatientDetail,ApiStaff} from '#lib/types/clinic.ts';
 let {open=$bindable(true),facilityId,patientId,onSaved,onClose}:{open?:boolean;facilityId:string;patientId:string;onSaved:()=>void;onClose:()=>void}=$props();let patient=$state<ApiPatientDetail|null>(null),staff=$state<ApiStaff[]>([]),loading=$state(true),busy=$state(false),error=$state(''),message=$state(''),revision=$state(0),phone=$state(''),address=$state(''),emergency=$state(''),history=$state(''),allergy=$state(''),preferred=$state(''),active=$state(true),confirm=$state(false);
 $effect(()=>{if(!open){onClose();return;}const fid=facilityId,id=patientId,r=revision;void r;let live=true;loading=true;error='';Promise.all([adminClinicsApi.patients.get(fid,id),adminClinicsApi.staff.list(fid)]).then(([p,s])=>{if(live){patient=p;staff=s;phone=p.phone??'';address=p.address??'';emergency=p.emergency_contact??'';history=p.medical_history??'';allergy=p.allergy_info??'';preferred=p.preferred_staff_id??'';active=p.is_active;}}).catch(e=>{if(live)error=apiMessage(e,'客戶檔案載入失敗');}).finally(()=>{if(live)loading=false;});return()=>{live=false;};});
 async function save(e?:SubmitEvent){e?.preventDefault();if(!patient)return;if(active!==patient.is_active&&!confirm){confirm=true;return;}busy=true;error='';try{patient=await adminClinicsApi.patients.update(facilityId,patientId,{phone:phone.trim(),address:address.trim()||null,emergency_contact:emergency.trim()||null,medical_history:history.trim()||null,allergy_info:allergy.trim()||null,preferred_staff_id:preferred||null,is_active:active});confirm=false;message='客戶檔案已儲存';onSaved();}catch(e){error=apiMessage(e,'客戶檔案儲存失敗');}finally{busy=false;}}
 const stamp=(v:string|null)=>v?new Date(v).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):'未記錄';
</script>
<Modal bind:open title={patient?patient.name+'・客戶檔案':'客戶檔案'} description="身分資料用於識別，姓名、生日與身分證末四碼僅供檢視。" {busy}><div class="space-y-5"><Feedback {error} {message}/>{#if loading}<p role="status">載入客戶檔案中…</p>{:else if patient}<dl class="grid grid-cols-2 gap-3 rounded-xl bg-muted/40 p-4 text-sm"><div><dt class="text-muted-foreground">生日／性別</dt><dd>{patient.birth_date??'未填'} · {patient.gender==='M'?'男':patient.gender==='F'?'女':'未填'}</dd></div><div><dt class="text-muted-foreground">身分證末四碼</dt><dd>{patient.national_id_last4??'未記錄'}</dd></div><div><dt class="text-muted-foreground">會員綁定</dt><dd>{patient.member_linked?'已綁定':'現場客戶'}</dd></div><div><dt class="text-muted-foreground">建立時間</dt><dd>{stamp(patient.created_at)}</dd></div></dl><div class="grid grid-cols-3 gap-2">{#each [{label:'總預約',value:patient.stats.total},{label:'已完成',value:patient.stats.completed},{label:'已取消',value:patient.stats.cancelled},{label:'未到',value:patient.stats.no_show},{label:'未來預約',value:patient.stats.upcoming},{label:'未到率',value:(patient.stats.no_show_rate*100).toFixed(1)+'%'}] as item (item.label)}<div class="rounded-xl border p-3"><p class="text-xs text-muted-foreground">{item.label}</p><p class="text-lg font-semibold">{item.value}</p></div>{/each}</div><p class="text-sm text-muted-foreground">首次就診 {patient.stats.first_visit??'無'} · 最近就診 {patient.stats.last_visit??'無'} · 常見人員 {patient.stats.top_staff_name??'無'}</p><form onsubmit={save} class="space-y-4"><fieldset disabled={busy} class="space-y-4"><legend>聯絡方式與照護註記</legend><label>電話<input type="tel" bind:value={phone}/></label><label>地址<input bind:value={address}/></label><label>緊急聯絡人<input bind:value={emergency}/></label><label>病史<textarea bind:value={history}></textarea></label><label>過敏資訊<textarea bind:value={allergy}></textarea></label><label>偏好人員<select aria-label="偏好人員" bind:value={preferred}><option value="">無偏好</option>{#each staff as s (s.id)}<option value={s.id}>{s.name}{s.is_active?'':'（停用）'}</option>{/each}</select></label><label><input type="checkbox" bind:checked={active}/>啟用客戶檔案</label></fieldset>{#if confirm}<div class="space-y-3 rounded-xl border border-destructive/30 p-3"><p class="text-sm">確認將「{patient.name}」{active?'啟用':'停用'}？停用後無法從客戶列表直接再次預約。</p><div class="flex gap-2"><Button disabled={busy} variant="outline" onclick={()=>{confirm=false;active=patient!.is_active;}}>取消變更狀態</Button><Button disabled={busy} onclick={()=>save()}>確認並儲存檔案</Button></div></div>{:else}<Button type="submit" disabled={busy}>儲存客戶檔案</Button>{/if}</form><section class="space-y-3 border-t pt-5"><h2 class="font-semibold">預約時間軸</h2>{#each patient.timeline as t (t.appointment_id)}<article class="space-y-2 rounded-xl border p-4"><div class="flex flex-wrap items-center justify-between gap-2"><p class="font-medium">{t.appointment_date} {t.appointment_time.slice(0,5)}</p><StatusPill status={t.status}/></div><p class="text-sm">{t.service_name??'一般預約'} · {t.staff_name??'不指定人員'} · {{phone:'電話',walk_in:'現場',online:'線上'}[t.booking_method]} · 號碼 {t.queue_number??'無'}</p>{#if t.check_in_time}<p class="text-xs text-muted-foreground">報到：{stamp(t.check_in_time)}</p>{/if}{#if t.notes}<p class="whitespace-pre-wrap text-sm">備註：{t.notes}</p>{/if}<details><summary class="cursor-pointer text-sm text-primary">狀態變更紀錄</summary><ul class="mt-2 space-y-2 text-xs text-muted-foreground">{#each t.events as ev,i (i)}<li>{stamp(ev.created_at)} · {APPOINTMENT_STATUS_LABELS[ev.from_status]} → {APPOINTMENT_STATUS_LABELS[ev.to_status]} {ev.reason??''}</li>{:else}<li>尚無狀態變更紀錄。</li>{/each}</ul></details></article>{:else}<p class="text-sm text-muted-foreground">尚無預約歷程。</p>{/each}</section>{:else}<Button variant="outline" onclick={()=>revision++}>重試客戶檔案</Button>{/if}</div></Modal>
